/**
 * POS feature types — explicit interfaces using shared domain types.
 *
 * This module defines all types used by the POS feature, importing from
 * `shared/types/` as the single source of truth for domain entities.
 */

import type { Product } from '@shared/types/product.js'
import type { Customer } from '@shared/types/customer.js'

// ============================================================================
// Shared Type Aliases — derived from shared types
// ============================================================================

/** Compact catalog item for list/table display and cart operations. */
export interface PartCatalogItem extends Pick<Product, 'id' | 'barcode' | 'name' | 'priceNet' | 'quantityOnHand'> {}

/** Customer selector item for dropdown selectors (compact shape). */
export interface CustomerSelectorItem extends Pick<Customer, 'id' | 'type'> {
  /** Human-readable name: "firstName lastName" for private, companyName for company. */
  displayName: string
}

// ============================================================================
// Cart Types — internal to the POS feature
// ============================================================================

/** VAT rate ID constants — matches server vatRates table. */
export const VAT_RATES = {
  'vat-standard': 2100, // 21%
  'vat-reduced': 600,   // 6%
  'vat-zero': 0,        // 0%
} as const

/** Default VAT rate for parts. */
export const DEFAULT_VAT_RATE = 'vat-standard' as const

/** A single line item in the cart (with computed totals). */
export interface CartLineItem {
  partId: string
  barcode: string
  name: string
  priceNet: number // ex-tax cents per unit (snapshot at add time)
  quantity: number
  vatRateId: keyof typeof VAT_RATES
  discountPercent: number | null // basis points, e.g. 1000 = 10%
  // Computed totals (updated whenever qty/discount changes)
  lineTotalNet: number
  lineTotalVat: number
  lineTotalGross: number
}

// ============================================================================
// Checkout Types — request/response shapes for the checkout flow
// ============================================================================

/** Payload sent to POST /sales for checkout. */
export interface CheckoutPayload {
  customerId: string | null
  paymentMethod: 'cash' | 'card'
  lineItems: Array<{
    partId: string
    quantity: number
    unitPriceNet: number
    vatRateId: string
    description: string
  }>
}

/** Success info returned from POST /sales. */
export interface CheckoutSuccess {
  saleNumber: string
  totalGross: number
}

import { Card, CardContent } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { useCartStore, VAT_RATES } from '../store'

// ============================================================================
// Component — Cart Display
// ============================================================================

export function CartDisplay() {
  const lineItems = useCartStore((s) => s.lineItems)
  const subtotalNet = useCartStore((s) => s.subtotalNet)
  const vatTotal = useCartStore((s) => s.vatTotal)
  const totalGross = useCartStore((s) => s.totalGross)
  const updateQuantity = useCartStore((s) => s.updateQuantity)
  const removeLineItem = useCartStore((s) => s.removeLineItem)
  const changeVatRate = useCartStore((s) => s.changeVatRate)

  if (lineItems.length === 0) {
    return (
      <Card>
        <CardContent className="p-6">
          <div className="text-center text-muted-foreground py-8">
            Cart is empty — search for parts above to add items
          </div>
        </CardContent>
      </Card>
    )
  }

  return (
    <Card>
      <CardContent className="p-0">
        {/* Line items list */}
        <div className="divide-y max-h-[400px] overflow-y-auto">
          {lineItems.map((item) => (
            <CartLineItemRow
              key={item.partId}
              item={item}
              onUpdateQuantity={updateQuantity}
              onVatChange={changeVatRate}
              onRemove={removeLineItem}
            />
          ))}
        </div>

        {/* Running totals */}
        <div className="border-t p-4 space-y-1">
          <div className="flex justify-between text-sm">
            <span className="text-muted-foreground">Subtotal (net)</span>
            <span className="font-mono">{formatPrice(subtotalNet)}</span>
          </div>
          <div className="flex justify-between text-sm">
            <span className="text-muted-foreground">VAT</span>
            <span className="font-mono">{formatPrice(vatTotal)}</span>
          </div>
          <div className="flex justify-between font-bold text-base pt-2 border-t">
            <span>Total (gross)</span>
            <span className="font-mono">{formatPrice(totalGross)}</span>
          </div>
        </div>
      </CardContent>
    </Card>
  )
}

// ============================================================================
// Sub-component — Single Line Item Row
// ============================================================================

interface CartLineItemRowProps {
  item: ReturnType<typeof useCartStore.getState>['lineItems'][number]
  onUpdateQuantity: (partId: string, quantity: number) => void
  onVatChange: (partId: string, newVatRateId: keyof typeof VAT_RATES) => void
  onRemove: (partId: string) => void
}

function CartLineItemRow({ item, onUpdateQuantity, onVatChange, onRemove }: CartLineItemRowProps) {
  return (
    <div className="p-3 flex items-center gap-3">
      {/* VAT rate selector */}
      <select
        value={item.vatRateId}
        onChange={(e) => onVatChange(item.partId, e.target.value as keyof typeof VAT_RATES)}
        className="h-7 px-1 text-xs border rounded bg-background font-mono shrink-0"
        title="VAT rate"
      >
        <option value="vat-zero">0%</option>
        <option value="vat-reduced">6%</option>
        <option value="vat-standard">21%</option>
      </select>

      {/* Quantity controls */}
      <div className="flex items-center gap-1 shrink-0">
        <Button
          variant="outline"
          size="sm"
          onClick={() => onUpdateQuantity(item.partId, item.quantity - 1)}
          className="h-7 w-7 p-0"
        >
          −
        </Button>
        <span className="w-8 text-center text-sm font-medium">{item.quantity}</span>
        <Button
          variant="outline"
          size="sm"
          onClick={() => onUpdateQuantity(item.partId, item.quantity + 1)}
          className="h-7 w-7 p-0"
        >
          +
        </Button>
      </div>

      {/* Part info */}
      <div className="flex-1 min-w-0">
        <div className="text-sm font-medium truncate">{item.name}</div>
        <div className="text-xs text-muted-foreground flex items-center gap-2">
          <span>{formatPrice(item.priceNet)} each × {item.quantity}</span>
          <span className="text-muted-foreground/60">·</span>
          <span className="text-muted-foreground/80 font-mono">
            VAT: {VAT_RATES[item.vatRateId] / 100}%
          </span>
        </div>
      </div>

      {/* Line total */}
      <div className="text-right shrink-0">
        <div className="font-mono text-sm font-medium">{formatPrice(item.lineTotalGross)}</div>
        <Button
          variant="ghost"
          size="sm"
          onClick={() => onRemove(item.partId)}
          className="h-5 px-1 text-xs text-destructive hover:text-destructive"
        >
          ✕
        </Button>
      </div>
    </div>
  )
}

