describe('Cart Store — line total math', () => {
  beforeEach(() => createFreshStore())

  it('computes correct net total: quantity × unitPriceNet', () => {
    useCartStore.getState().addLineItem(mockPart, 3) // 500 × 3 = 1500

    const state = useCartStore.getState()
    expect(state.lineItems[0].lineTotalNet).toBe(1500)
  })

  it('computes correct gross total with VAT: net + (net × vatRateBps / 10000)', () => {
    // Standard VAT rate = 21% = 2100 basis points
    useCartStore.getState().addLineItem(mockPart, 3) // priceNet=500, qty=3 → net=1500

    const state = useCartStore.getState()
    const line = state.lineItems[0]
    // VAT: 1500 × 2100 / 10000 = 315
    expect(line.lineTotalVat).toBe(315)
    // Gross: 1500 + 315 = 1815
    expect(line.lineTotalGross).toBe(1815)
  })

  it('computes correct totals with discount (in basis points)', () => {
    useCartStore.getState().addLineItem(mockPart, 2) // priceNet=500, qty=2 → gross net = 1000
    // Apply 10% discount = 1000 bps: discounted per unit = 500 × (1 - 1000/10000) = 450
    // lineNetTotal = 450 × 2 = 900
    useCartStore.getState().applyDiscount(mockPart.id, 1000)

    const state = useCartStore.getState()
    const line = state.lineItems[0]
    expect(line.discountPercent).toBe(1000) // 10% in bps
    expect(line.lineTotalNet).toBe(900) // 450 × 2
    // VAT: 900 × 2100 / 10000 = 189
    expect(line.lineTotalVat).toBe(189)
    // Gross: 900 + 189 = 1089
    expect(line.lineTotalGross).toBe(1089)
  })

  it('handles zero quantity line item totals', () => {
    useCartStore.getState().addLineItem(mockPart, 0) // should be removed or have 0 qty

    const state = useCartStore.getState()
    expect(state.lineItems).toHaveLength(0) // 0 qty removes the line
  })
})

